export type Entry<T> = { readonly value: T; readonly expiresAt: number };

export const setEntry = <T>(store: Map<string, Entry<T>>, key: string, value: T, ttlMs: number): void => {
  // Negative TTLs indicate an already-expired upstream response; skip storing to avoid poisoning the cache with stale errors.
  if (ttlMs <= 0) return;
  store.set(key, { value, expiresAt: Date.now() + ttlMs });
};
